INSERT INTO permissions(code) VALUES ('VEHICLE_OWNERSHIP_READ'),('VEHICLE_OWNERSHIP_WRITE'),('VEHICLE_ODOMETER_WRITE'),('DOCUMENT_READ'),('DOCUMENT_WRITE');
INSERT INTO role_permissions(role,permission) SELECT r.code,p.code FROM roles r CROSS JOIN permissions p WHERE r.code IN ('BRAND_OWNER','REGIONAL_MANAGER','BRANCH_MANAGER','SERVICE_ADVISOR') AND p.code IN ('VEHICLE_OWNERSHIP_READ','VEHICLE_OWNERSHIP_WRITE','VEHICLE_ODOMETER_WRITE','DOCUMENT_READ','DOCUMENT_WRITE');
INSERT INTO role_permissions(role,permission) VALUES ('MECHANIC','VEHICLE_ODOMETER_WRITE'),('MECHANIC','DOCUMENT_READ');
